export interface College {
  id: number; slug: string; name: string; location: string; state: string; region: string;
  lat: number; lng: number; mapX: number; mapY: number;
  affiliation: string; conference: string; tier: Tier; programType: string;
  draftPicks: number;
  mlrPlayed: number | null;      // confirmed to have played >= 1 MLR match. null = n/a (no draftees)
  mlrUnconfirmed: number;        // drafted, played-or-not not confirmed either way
  mlrNoAppearance: number;       // drafted, no recorded MLR appearance
  mlrNotYet: number;             // drafted in 2026, no season played yet
  mlrNote?: string;
  playerCount: number;
  coachName: string; coachEmail: string;
  /** Public recruitment / interest form on the school site. Omit when unknown. */
  recruitmentFormUrl?: string;
  rugbyProgramUrl: string; assistantCoaches: { name: string; email: string }[];
  description: string; enrollment: number; popularMajors: string[];
  weatherSummary: string; monthlyTemps: MonthTemp[];
  badges: string[]; achievements: string[];
  website: string; imageUrl: string; imageCredit: string; imageSourcePage: string; gender: Gender;
}

